#include <bits/stdc++.h>
using namespace std;

using ll = long long;

const int maxn = 3e3 + 10;
const ll linf = 0x3f3f3f3f3f3f3f3fLL;

int n, m, ta[maxn], tb[maxn], sz[maxn];
vector<int> v[maxn];

struct DP {
    int a;
    ll b;

    DP(int a_ = 0, ll b_ = -linf) : a(a_), b(b_) {}
};

DP dp[maxn][maxn];

bool operator<(const DP& a, const DP& b) {
    if (a.a != b.a) return a.a < b.a;
    return a.b < b.b;
}

void dfs(int x, int parent) {
    sz[x] = 1;
    dp[x][0] = DP(0, static_cast<ll>(tb[x]) - ta[x]);

    for (int y : v[x]) {
        if (y == parent) continue;

        dfs(y, x);

        vector<DP> tmp(sz[x] + sz[y]);
        for (int i = 0; i < sz[x]; ++i) {
            for (int j = 0; j <= sz[y]; ++j) {
                DP candidate(
                    dp[x][i].a + dp[y][j].a,
                    dp[x][i].b + dp[y][j].b
                );
                tmp[i + j] = max(tmp[i + j], candidate);
            }
        }

        sz[x] += sz[y];
        for (int i = 0; i < sz[x]; ++i) {
            dp[x][i] = tmp[i];
        }
    }

    dp[x][sz[x]] = DP(
        dp[x][sz[x] - 1].a + (dp[x][sz[x] - 1].b > 0),
        0
    );
}

int main() {
    int t;
    scanf("%d", &t);

    while (t--) {
        scanf("%d%d", &n, &m);

        for (int i = 1; i <= n; ++i) {
            v[i].clear();
            scanf("%d", &ta[i]);
        }

        for (int i = 1; i <= n; ++i) {
            scanf("%d", &tb[i]);
        }

        for (int i = 0; i < n - 1; ++i) {
            int a, b;
            scanf("%d%d", &a, &b);
            v[a].push_back(b);
            v[b].push_back(a);
        }

        dfs(1, 0);
        printf("%d\n", dp[1][m - 1].a + (dp[1][m - 1].b > 0));
    }

    return 0;
}

